def tarantula_fault_suspiciousness(ef: int, nf: int, ep: int, np_count: int) -> float:
    e_f = max(0, int(ef))
    n_f = max(0, int(nf))
    e_p = max(0, int(ep))
    n_p = max(0, int(np_count))
    total_f = e_f + n_f
    total_p = e_p + n_p
    if total_f == 0 or e_f == 0:
        return 0.0
    fail_ratio = e_f / float(total_f)
    if total_p == 0:
        return 1.0
    pass_ratio = e_p / float(total_p)
    if fail_ratio + pass_ratio == 0.0:
        return 0.0
    return fail_ratio / (fail_ratio + pass_ratio)

def git_bisect_midpoint_step(good_idx: int, bad_idx: int) -> int:
    lo = min(int(good_idx), int(bad_idx))
    hi = max(int(good_idx), int(bad_idx))
    if hi - lo <= 1:
        return hi
    return lo + (hi - lo) // 2

def repair_loop_termination_decide(failing_tests: int, attempt: int, max_attempts: int, prev_failing_tests: int) -> int:
    if int(failing_tests) <= 0:
        return 1
    if int(attempt) >= max(1, int(max_attempts)):
        return -1
    if int(attempt) > 1 and int(failing_tests) >= int(prev_failing_tests):
        return -2
    return 0

def weighted_rrf_rank_fusion(lexical_rank: int, semantic_rank: int, k_constant: int, semantic_weight: float) -> float:
    r_lex = max(1, abs(int(lexical_rank)))
    r_sem = max(1, abs(int(semantic_rank)))
    k = max(1, abs(int(k_constant)))
    w = max(0.0, min(1.0, float(semantic_weight)))
    return (1.0 - w) / float(k + r_lex) + w / float(k + r_sem)
